  app.get("/api/telehealth/portal/dashboard", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      if (!userId) return res.status(401).json({ error: "Unauthorized" });

      const { telehealthService } = await import("../telehealth-service");
      await telehealthService.seedDemoVisits(userId);

      const upcomingVisits = await telehealthService.getVisitsForPatient(userId, "upcoming");
      const pastVisits = await telehealthService.getVisitsForPatient(userId, "past");

      const completedCount = pastVisits.filter((v: any) => v.status === "completed").length;
      const avgRating = pastVisits
        .filter((v: any) => v.rating)
        .reduce((sum: number, v: any, _: number, arr: any[]) => sum + (v.rating || 0) / arr.length, 0);

      const nextVisit = upcomingVisits.length > 0 ? upcomingVisits[0] : null;

      let unreadMessages = 0;

      let educationModules: any[] = [];

      const recentSummaries = pastVisits
        .filter((v: any) => v.aiSummary)
        .slice(0, 3)
        .map((v: any) => ({
          id: v.id,
          title: v.title,
          date: v.scheduledAt,
          summary: v.aiSummary,
          providerName: v.providerName,
        }));

      res.json({
        upcomingVisits,
        pastVisits: pastVisits.slice(0, 10),
        stats: {
          totalVisits: completedCount,
          upcomingCount: upcomingVisits.length,
          averageRating: Math.round(avgRating * 10) / 10,
          unreadMessages,
        },
        nextVisit,
        recentSummaries,
        educationModules: educationModules.map((m: any) => ({
          id: m.id,
          title: m.title,
          description: m.description,
          category: m.category,
          difficulty: m.difficulty_level || m.difficultyLevel,
          duration: m.estimated_minutes || m.estimatedMinutes,
        })),
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message || "Failed to load portal dashboard" });
    }
  });


