  app.post("/api/telehealth/visits", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);

      const { title, reason, visitType, scheduledAt, duration, chiefComplaint, providerName, providerSpecialty } = req.body as any;
      if (!title || !visitType || !scheduledAt) {
        return res.status(400).json({ error: "title, visitType, and scheduledAt are required" });
      }

      const { telehealthService } = await import("../telehealth-service");
      const visit = await telehealthService.scheduleVisit({
        patientId: userId,
        title,
        reason,
        visitType,
        scheduledAt: new Date(scheduledAt),
        duration: duration || 30,
        chiefComplaint,
        providerName,
        providerSpecialty,
      });

      auditLog(req, "telehealth_visit_scheduled", "telehealth_visit", visit.id, { visitType });

      try {
        await appointmentReminderService.scheduleRemindersForVisit(visit.id);
      } catch (reminderErr) {
        console.error("Failed to schedule reminders:", reminderErr);
      }

      res.status(201).json({ visit });
    } catch (error: any) {
      res.status(500).json({ error: error.message || "Failed to schedule visit" });
    }
  });


  app.patch("/api/telehealth/visits/:id/status", requireAuth, async (req: Request, res: Response) => {
    try {
      const visitId = getParam(req, "id");
      const userId = getUserId(req);
      const { status } = req.body as any;
      if (!status) return res.status(400).json({ error: "status is required" });

      if (!await assertVisitOwner(visitId, userId, res)) return;
      const { telehealthService } = await import("../telehealth-service");
      const visit = await telehealthService.updateVisitStatus(visitId, status);
      auditLog(req, `telehealth_visit_${status}`, "telehealth_visit", visitId);

      if (status === "completed" && visit) {
        try {
          const userId = getUserId(req);
          const recordData = {
            userId,
            title: visit.title || "Telehealth Visit",
            type: "visit",
            date: visit.scheduledAt || new Date(),
            provider: visit.providerName || "Telehealth Provider",
            source: "telehealth",
            summary: visit.aiVisitSummary || `${visit.visitType?.replace(/_/g, " ")} telehealth visit`,
            metadata: {
              telehealthVisitId: visit.id,
              visitType: visit.visitType,
              duration: visit.actualDuration || visit.duration,
              providerSpecialty: visit.providerSpecialty,
            },
          };

          const existingRecord = await db.select().from(healthRecords)
            .where(and(
              eq(healthRecords.userId, userId),
              sql`metadata->>'telehealthVisitId' = ${visit.id}`
            ))
            .limit(1);

          if (existingRecord.length === 0) {
            await db.insert(healthRecords).values(recordData);
          }
        } catch (recordErr) {
          console.error("[Telehealth] Failed to create health record:", recordErr);
        }
      }

      res.json({ visit });
    } catch (error: any) {
      res.status(500).json({ error: error.message || "Failed to update visit status" });
    }
  });


