      const { id: visitId } = req.params as any;
      const userId = getUserId(req);
      if (!await assertVisitOwner(visitId, userId, res)) return;
      const { telehealthService } = await import("../telehealth-service");
      const { sessionSecurity } = await import("../telehealth-service");
      const visit = await telehealthService.getVisitById(visitId);

      const sessionId = visit.roomId || visitId;
      const logs = sessionSecurity.getSessionLogs(sessionId);
      const integrityVerified = sessionSecurity.verifySessionIntegrity(sessionId);

      res.json({
        visitId,
        sessionId,
        encryptionProtocol: "AES-256-GCM",
        keyExchange: "ECDHE-P384",
        tlsVersion: "1.3",
        integrityVerified,
        sessionLogs: logs,
        complianceStatus: {
          hipaaCompliant: true,
          encryptionAtRest: true,
          encryptionInTransit: true,
          auditLogged: true,
        },
      });
