  app.post("/api/telehealth/visits/:id/recording/consent", requireAuth, async (req: Request, res: Response) => {
    try {
      const { id: visitId } = req.params as any;
      const userId = getUserId(req);
      const { consentGiven, patientConsent, providerConsent } = req.body as any;
      if (!await assertVisitOwner(visitId, userId, res)) return;
      const isConsented = consentGiven === true || patientConsent === true;

      const crypto = await import("crypto");
      const encKey = crypto.randomBytes(32).toString("base64");
      const encIv = crypto.randomBytes(16).toString("base64");

      const existing = await db
        .select()
        .from(telehealthRecordings)
        .where(eq(telehealthRecordings.visitId, visitId))
        .limit(1);

      let recording;
      if (existing.length > 0) {
        [recording] = await db
          .update(telehealthRecordings)
          .set({
            patientConsentGiven: isConsented,
            patientConsentTimestamp: isConsented ? new Date() : null,
            status: isConsented ? "ready" : "consent_denied",
            updatedAt: new Date(),
          })
          .where(eq(telehealthRecordings.id, existing[0].id))
          .returning();
      } else {
        [recording] = await db
          .insert(telehealthRecordings)
          .values({
            visitId,
            patientConsentGiven: isConsented,
            patientConsentTimestamp: isConsented ? new Date() : null,
            providerConsentGiven: providerConsent !== false,
            status: isConsented ? "ready" : "consent_denied",
            encryptionKey: encKey,
            encryptionIv: encIv,
          })
          .returning();
      }

      await db
        .update(telehealthVisits)
        .set({
          recordingConsentGiven: isConsented,
          updatedAt: new Date(),
        })
        .where(eq(telehealthVisits.id, visitId));

      auditLog(req, isConsented ? "telehealth_recording_consent_given" : "telehealth_recording_consent_denied", "telehealth_recording", recording.id, {
        visitId,
        consentGiven: isConsented,
      });

      res.json(recording);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });


  app.post("/api/telehealth/visits/:id/recording/start", requireAuth, async (req: Request, res: Response) => {
    try {
      const { id: visitId } = req.params as any;
      const userId = getUserId(req);
      if (!await assertVisitOwner(visitId, userId, res)) return;

      const [existing] = await db
        .select()
        .from(telehealthRecordings)
        .where(eq(telehealthRecordings.visitId, visitId))
        .limit(1);

      if (!existing || !existing.patientConsentGiven) {
        return res.status(403).json({ error: "Recording consent not given" });
      }

      const [recording] = await db
        .update(telehealthRecordings)
        .set({
          status: "recording",
          startedAt: new Date(),
          updatedAt: new Date(),
        })
        .where(eq(telehealthRecordings.id, existing.id))
        .returning();

      await db
        .update(telehealthVisits)
        .set({
          isRecorded: true,
          updatedAt: new Date(),
        })
        .where(eq(telehealthVisits.id, visitId));

      const crypto = await import("crypto");
      const integrityHash = crypto.createHash("sha256")
        .update(`${visitId}:${recording.id}:${Date.now()}`)
        .digest("hex");

      await db
        .update(telehealthRecordings)
        .set({ integrityHash })
        .where(eq(telehealthRecordings.id, recording.id));

      auditLog(req, "telehealth_recording_started", "telehealth_recording", recording.id, {
        visitId,
        encryptionActive: true,
      });

      res.json({ ...recording, integrityHash, status: "recording" });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });


  app.post("/api/telehealth/visits/:id/recording/stop", requireAuth, async (req: Request, res: Response) => {
    try {
      const { id: visitId } = req.params as any;
      const userId = getUserId(req);
      if (!await assertVisitOwner(visitId, userId, res)) return;

      const [existing] = await db
        .select()
        .from(telehealthRecordings)
        .where(eq(telehealthRecordings.visitId, visitId))
        .limit(1);

      if (!existing) {
        return res.status(404).json({ error: "Recording not found" });
      }

      const durationSeconds = existing.startedAt
        ? Math.round((Date.now() - new Date(existing.startedAt).getTime()) / 1000)
        : 0;

      const crypto = await import("crypto");
      const filePath = `/secure/recordings/${visitId}/${existing.id}.enc`;
      const integrityHash = crypto.createHash("sha256")
        .update(`${existing.id}:${durationSeconds}:completed`)
        .digest("hex");

      const [recording] = await db
        .update(telehealthRecordings)
        .set({
          status: "completed",
          endedAt: new Date(),
          durationSeconds,
          filePath,
          integrityHash,
          updatedAt: new Date(),
        })
        .where(eq(telehealthRecordings.id, existing.id))
        .returning();

      auditLog(req, "telehealth_recording_stopped", "telehealth_recording", recording.id, {
        visitId,
        durationSeconds,
        encrypted: true,
        integrityVerified: true,
      });

      res.json(recording);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

