  // =============== UNIFIED CHRONOLOGICAL SUMMARY ===============


  app.get("/api/unified-chronological-summary", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const [records, profile, allAppointments] = await Promise.all([
        storage.getHealthRecords(userId),
        storage.getPatientProfile(userId),
        storage.getAppointments(userId),
      ]);

      function safeDate(val: any): string {
        if (!val) return new Date().toISOString();
        try {
          const d = new Date(val);
          return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
        } catch { return new Date().toISOString(); }
      }

      type TimelineEvent = {
        id: string;
        date: string;
        category: string;
        title: string;
        detail: string;
        source: string;
        priority?: string;
        metadata?: Record<string, any>;
      };

      const events: TimelineEvent[] = [];

      for (const r of records) {
        events.push({
          id: r.id,
          date: safeDate(r.date || r.createdAt),
          category: r.type || "other",
          title: r.title || "Unknown",
          detail: r.summary || "",
          source: (r as any).source || "manual",
          priority: (r as any).priority || undefined,
          metadata: {
            provider: (r as any).provider,
            facility: (r as any).facility,
            fhirResourceType: (r as any).fhirResourceType,
          },
        });
      }

      for (const appt of allAppointments) {
        events.push({
          id: appt.id,
          date: safeDate(appt.scheduledAt),
          category: "appointment",
          title: (appt as any).title || `${(appt as any).type || "Appointment"}`,
          detail: (appt as any).providerName ? `With ${(appt as any).providerName}` : "",
          source: "appointment",
          priority: undefined,
          metadata: {
            status: (appt as any).status,
            type: (appt as any).type,
            provider: (appt as any).providerName,
            location: (appt as any).location,
          },
        });
      }

      const p = profile as any;
      const profileCreatedDate = safeDate(p?.createdAt);

      if (Array.isArray(p?.healthConditions)) {
        for (const c of p.healthConditions) {
          const name = typeof c === "string" ? c : c?.name || "";
          if (!name) continue;
          const existing = events.find(e => e.category === "condition" && e.title.toLowerCase() === name.toLowerCase());
          if (!existing) {
            events.push({
              id: `profile-condition-${name}`,
              date: (typeof c === "object" && c?.diagnosedDate) ? safeDate(c.diagnosedDate) : profileCreatedDate,
              category: "condition",
              title: name,
              detail: typeof c === "object" ? [c.icdCode, c.status].filter(Boolean).join(" - ") : "",
              source: "intake",
            });
          }
        }
      }

      if (Array.isArray(p?.medications)) {
        for (const m of p.medications) {
          const name = typeof m === "string" ? m : m?.name || "";
          if (!name) continue;
          const existing = events.find(e => e.category === "medication" && e.title.toLowerCase().includes(name.toLowerCase()));
          if (!existing) {
            events.push({
              id: `profile-med-${name}`,
              date: profileCreatedDate,
              category: "medication",
              title: name,
              detail: typeof m === "object" ? [m.dosage, m.frequency].filter(Boolean).join(" ") : "",
              source: "intake",
            });
          }
        }
      }

      if (Array.isArray(p?.allergies)) {
        for (const a of p.allergies) {
          const allergen = typeof a === "string" ? a : a?.allergen || a?.name || "";
          if (!allergen) continue;
          const existing = events.find(e => e.category === "allergy" && e.title.toLowerCase() === allergen.toLowerCase());
          if (!existing) {
            events.push({
              id: `profile-allergy-${allergen}`,
              date: profileCreatedDate,
              category: "allergy",
              title: allergen,
              detail: typeof a === "object" ? [a.reaction, a.severity].filter(Boolean).join(" - ") : "",
              source: "intake",
            });
          }
        }
      }

      if (Array.isArray(p?.surgeries)) {
        for (const s of p.surgeries) {
          const name = typeof s === "string" ? s : s?.name || "";
          if (!name) continue;
          const existing = events.find(e => e.category === "procedure" && e.title.toLowerCase() === name.toLowerCase());
          if (!existing) {
            events.push({
              id: `profile-surgery-${name}`,
              date: (typeof s === "object" && s?.date) ? safeDate(s.date) : profileCreatedDate,
              category: "procedure",
              title: name,
              detail: typeof s === "object" && s?.notes ? s.notes : "",
              source: "intake",
            });
          }
        }
      }

      if (Array.isArray(p?.familyHistory)) {
        for (const f of p.familyHistory) {
          const condition = typeof f === "string" ? f : f?.condition || "";
          if (!condition) continue;
          events.push({
            id: `profile-family-${condition}`,
            date: profileCreatedDate,
            category: "family_history",
            title: condition,
            detail: typeof f === "object" && f?.relation ? `Family member: ${f.relation}` : "",
            source: "intake",
          });
        }
      }

      events.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      const grouped: Record<string, TimelineEvent[]> = {};
      for (const ev of events) {
        const d = new Date(ev.date);
        const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
        if (!grouped[key]) grouped[key] = [];
        grouped[key].push(ev);
      }

      const periods = Object.entries(grouped)
        .sort(([a], [b]) => b.localeCompare(a))
        .map(([period, items]) => {
          const [year, month] = period.split("-");
          const monthName = new Date(parseInt(year), parseInt(month) - 1).toLocaleString("en-US", { month: "long" });
          return { period, label: `${monthName} ${year}`, events: items };
        });

      const categoryCounts: Record<string, number> = {};
      for (const ev of events) {
        categoryCounts[ev.category] = (categoryCounts[ev.category] || 0) + 1;
      }

      const snapshot = {
        totalEvents: events.length,
        categories: categoryCounts,
        dateRange: events.length > 0 ? {
          earliest: events[events.length - 1].date,
          latest: events[0].date,
        } : null,
        profileName: p?.fullName || (p?.firstName ? `${p.firstName || ""} ${p.lastName || ""}`.trim() : undefined),
        dateOfBirth: p?.dateOfBirth,
        bloodType: p?.bloodType,
        emergencyContact: p?.emergencyContact,
      };

      res.json({
        snapshot,
        periods,
        totalEvents: events.length,
        generatedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error("Unified chronological summary error:", error);
      res.status(500).json({ error: "Failed to generate unified summary" });
    }
  });

