      const vitalsSummary = vitals.map(v => `${v.title}: ${v.summary || "recorded"} (${v.date ? new Date(v.date).toLocaleDateString() : "unknown"})`).join("; ");
      const labsSummary = labs.map(l => `${l.title}: ${l.summary || "recorded"} (${l.date ? new Date(l.date).toLocaleDateString() : "unknown"})`).join("; ");

