  app.post("/api/compliance-export/audit-logs", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req) || (req.headers["x-user-id"] as string) || "demo-user";
      const { format = "csv", encrypt = true, passphrase, dateFrom, dateTo } = req.body as any;

      if (encrypt && !passphrase) {
        return res.status(400).json({ error: "Passphrase is required for encrypted exports" });
      }
      if (!["pdf", "csv"].includes(format)) {
        return res.status(400).json({ error: "Format must be pdf or csv" });
      }

      const options = {
        format: format as "pdf" | "csv",
        encrypt: !!encrypt,
        passphrase,
        dateFrom: dateFrom ? new Date(dateFrom) : undefined,
        dateTo: dateTo ? new Date(dateTo) : undefined,
      };

      const logs = await complianceExportService.getAuditLogs(userId, options.dateFrom, options.dateTo);

      let buf: Buffer;
      let filename: string;
      let contentType: string;

      if (format === "pdf") {
        buf = await complianceExportService.generateAuditLogPDF(logs, options);
        filename = `audit-log-${new Date().toISOString().split("T")[0]}${encrypt ? ".encrypted" : ""}.pdf`;
        contentType = encrypt ? "application/octet-stream" : "application/pdf";
      } else {
        buf = complianceExportService.generateAuditLogCSV(logs, options);
        filename = `audit-log-${new Date().toISOString().split("T")[0]}${encrypt ? ".encrypted" : ""}.csv`;
        contentType = encrypt ? "application/octet-stream" : "text/csv";
      }

      auditLog(req, "export_compliance_audit", "audit_logs", undefined, {
        format,
        encrypted: encrypt,
        recordCount: logs.length,
      });

      res.setHeader("Content-Type", contentType);
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.setHeader("X-Content-Type-Options", "nosniff");
      res.send(buf);
    } catch (error: any) {
      console.error("Compliance audit export error:", error);
      res.status(500).json({ error: error.message || "Failed to export audit logs" });
    }
  });


  app.post("/api/compliance-export/tefca-exchanges", requireAuth, requireAdmin, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req) || (req.headers["x-user-id"] as string) || "demo-user";
      const { format = "csv", encrypt = true, passphrase, dateFrom, dateTo, networkId } = req.body as any;

      if (encrypt && !passphrase) {
        return res.status(400).json({ error: "Passphrase is required for encrypted exports" });
      }
      if (!["pdf", "csv"].includes(format)) {
        return res.status(400).json({ error: "Format must be pdf or csv" });
      }

      const options = {
        format: format as "pdf" | "csv",
        encrypt: !!encrypt,
        passphrase,
        dateFrom: dateFrom ? new Date(dateFrom) : undefined,
        dateTo: dateTo ? new Date(dateTo) : undefined,
      };

      let transactions = tefcaFrameworkService.getTransactions(undefined, 1000);
      let exchanges = transactions.length > 0
        ? transactions.map((t: any) => ({
            id: t.id,
            queryId: t.queryId,
            type: t.type,
            direction: t.direction,
            networkId: t.networkId,
            timestamp: t.timestamp,
            exchangePurpose: t.exchangePurpose,
            status: t.status,
            errorCode: t.errorCode,
            documentCount: t.documentIds?.length || 0,
            auditDetails: {
              requesterOrganization: t.auditDetails?.requesterOrganization || "Tabula Medica",
              consentVerified: t.auditDetails?.patientConsent?.hasConsent || false,
            },
          }))
        : generateDemoExchanges(networkId, 50);

      if (networkId) {
        exchanges = exchanges.filter((e: any) => e.networkId === networkId);
      }
      if (options.dateFrom) {
        exchanges = exchanges.filter((e: any) => new Date(e.timestamp) >= options.dateFrom!);
      }
      if (options.dateTo) {
        exchanges = exchanges.filter((e: any) => new Date(e.timestamp) <= options.dateTo!);
      }

      let buf: Buffer;
      let filename: string;
      let contentType: string;

      if (format === "pdf") {
        buf = await complianceExportService.generateTefcaExchangePDF(exchanges, options);
        filename = `tefca-exchanges-${new Date().toISOString().split("T")[0]}${encrypt ? ".encrypted" : ""}.pdf`;
        contentType = encrypt ? "application/octet-stream" : "application/pdf";
      } else {
        buf = complianceExportService.generateTefcaExchangeCSV(exchanges, options);
        filename = `tefca-exchanges-${new Date().toISOString().split("T")[0]}${encrypt ? ".encrypted" : ""}.csv`;
        contentType = encrypt ? "application/octet-stream" : "text/csv";
      }

      auditLog(req, "export_compliance_tefca", "tefca_exchange", undefined, {
        format,
        encrypted: encrypt,
        recordCount: exchanges.length,
        networkFilter: networkId || "all",
      });

      res.setHeader("Content-Type", contentType);
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.setHeader("X-Content-Type-Options", "nosniff");
      res.send(buf);
    } catch (error: any) {
      console.error("Compliance TEFCA export error:", error);
      res.status(500).json({ error: error.message || "Failed to export TEFCA exchanges" });
    }
  });


