      for (const f of fields) {
        if (req.body[f] !== undefined) updates[f] = req.body[f];
      }
      if (req.body.signedDate !== undefined) updates.signedDate = req.body.signedDate ? new Date(req.body.signedDate) : null;
      if (req.body.expirationDate !== undefined) updates.expirationDate = new Date(req.body.expirationDate);
      const agreement = await baaAgreementService.updateAgreement(userId, (req.params as any).id, updates);
      if (!agreement) return res.status(404).json({ error: "Agreement not found" });
