  app.post("/api/baa-agreements/:id/upload", requireAuth, uploadMiddleware.single("document"), async (req: Request, res: Response) => {
    try {
      const userId = getBaaUserId(req);
      if (!req.file) return res.status(400).json({ error: "No file uploaded" });
      const allowed = ["application/pdf", "image/jpeg", "image/png", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"];
      if (!allowed.includes(req.file.mimetype)) {
        fs.unlinkSync(req.file.path);
        return res.status(400).json({ error: "Invalid file type. Allowed: PDF, JPEG, PNG, DOC, DOCX" });
      }
      const agreement = await baaAgreementService.updateAgreement(userId, (req.params as any).id, {
        documentPath: req.file.path,
        documentName: req.file.originalname,
        documentMimeType: req.file.mimetype,
        documentSizeBytes: req.file.size,
      });
      if (!agreement) {
        fs.unlinkSync(req.file.path);
        return res.status(404).json({ error: "Agreement not found" });
      }
      res.json(agreement);
    } catch (error: any) {
      res.status(500).json({ error: error.message || "Failed to upload document" });
    }
  });


